-- Módulo 67 AdelantosPrestamos: adelantos y préstamos al personal, con su cronograma de cuotas mensuales.
-- Spec: docs/specs/modulo67-adelantos-prestamos-backend.md (§4).
-- DescuentosCuotaPrestamo.PlanillaId no tiene clave foránea: la añade el script del módulo 66 Planillas.

CREATE TABLE "Prestamos" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "Numero" character varying(20) NOT NULL,
    "EmpleadoId" integer NOT NULL,
    "Tipo" character varying(20) NOT NULL,
    "Monto" numeric(12,2) NOT NULL,
    "NumeroCuotas" integer NOT NULL,
    "FechaOtorgamiento" date NOT NULL,
    "PrimerAnio" integer NOT NULL,
    "PrimerMes" integer NOT NULL,
    "Motivo" character varying(300) NOT NULL,
    "Estado" character varying(20) NOT NULL,
    "Saldo" numeric(12,2) NOT NULL,
    "FechaAnulacion" date,
    "MotivoAnulacion" character varying(300),
    CONSTRAINT "PK_Prestamos" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_Prestamos_Empleados_EmpleadoId" FOREIGN KEY ("EmpleadoId") REFERENCES "Empleados" ("Id") ON DELETE RESTRICT,
    CONSTRAINT "CK_Prestamos_Tipo" CHECK ("Tipo" IN ('Adelanto', 'Prestamo')),
    CONSTRAINT "CK_Prestamos_Estado" CHECK ("Estado" IN ('Activo', 'Cancelado', 'Anulado')),
    CONSTRAINT "CK_Prestamos_Monto" CHECK ("Monto" > 0),
    CONSTRAINT "CK_Prestamos_NumeroCuotas" CHECK ("NumeroCuotas" BETWEEN 1 AND 24),
    CONSTRAINT "CK_Prestamos_PrimerMes" CHECK ("PrimerMes" BETWEEN 1 AND 12)
);
CREATE UNIQUE INDEX "IX_Prestamos_Numero" ON "Prestamos" ("Numero");
CREATE INDEX "IX_Prestamos_EmpleadoId" ON "Prestamos" ("EmpleadoId");

CREATE TABLE "CuotasPrestamo" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "PrestamoId" integer NOT NULL,
    "NumeroCuota" integer NOT NULL,
    "Anio" integer NOT NULL,
    "Mes" integer NOT NULL,
    "Monto" numeric(12,2) NOT NULL,
    "MontoDescontado" numeric(12,2) NOT NULL DEFAULT 0,
    "Estado" character varying(20) NOT NULL,
    CONSTRAINT "PK_CuotasPrestamo" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_CuotasPrestamo_Prestamos_PrestamoId" FOREIGN KEY ("PrestamoId") REFERENCES "Prestamos" ("Id") ON DELETE RESTRICT,
    CONSTRAINT "CK_CuotasPrestamo_Estado" CHECK ("Estado" IN ('Pendiente', 'Descontada')),
    CONSTRAINT "CK_CuotasPrestamo_Mes" CHECK ("Mes" BETWEEN 1 AND 12)
);
CREATE UNIQUE INDEX "IX_CuotasPrestamo_PrestamoId_NumeroCuota" ON "CuotasPrestamo" ("PrestamoId", "NumeroCuota");
CREATE INDEX "IX_CuotasPrestamo_Anio_Mes" ON "CuotasPrestamo" ("Anio", "Mes");

-- Un descuento por cada cuota que toca una planilla, para poder revertir una planilla sin afectar a las demás.
CREATE TABLE "DescuentosCuotaPrestamo" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "CuotaPrestamoId" integer NOT NULL,
    "PlanillaId" integer NOT NULL,
    "Monto" numeric(12,2) NOT NULL,
    CONSTRAINT "PK_DescuentosCuotaPrestamo" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_DescuentosCuotaPrestamo_CuotasPrestamo_CuotaPrestamoId" FOREIGN KEY ("CuotaPrestamoId") REFERENCES "CuotasPrestamo" ("Id") ON DELETE RESTRICT,
    CONSTRAINT "CK_DescuentosCuotaPrestamo_Monto" CHECK ("Monto" > 0)
);
CREATE INDEX "IX_DescuentosCuotaPrestamo_CuotaPrestamoId" ON "DescuentosCuotaPrestamo" ("CuotaPrestamoId");
CREATE INDEX "IX_DescuentosCuotaPrestamo_PlanillaId" ON "DescuentosCuotaPrestamo" ("PlanillaId");
